  "composition_summary": "Preserved the volatile tail unchanged (single user request, no justified repair). Authored one class-22 pure-logic draft pc-contrast-05: it reads raw slots via inputs.get('slots') so absence is a valid invalid-result, validates that the list has length 1..4 and every item is an exact integer in 5..9 (rejecting bool, float, non-integer and out-of-range), and assigns result={ok:boolean, slots:original if valid else []} on every branch without raising or performing I/O/host calls. The draft is an unapproved target-interface component only; no UUID, tests or approval were claimed, and no operation was executed.",
  "adjusted_volatile_messages": [["user", "Prepare the requested reusable draft without executing any operation."]],
  "settings_adjustments": [],
  "proposed_components": [
    {
      "class_code": 22,
      "payload": {
        "name": "pc-contrast-05",
        "description": "Pure-logic guard: validates a raw 'slots' list of length 1..4 with every item an exact integer in 5..9, and returns {ok, slots} where slots is the original list only when valid, else []. No I/O, imports, host calls or upstream validation assumption; result is assigned on every branch.",
        "content": "def classify_slots(raw):\n    slots = raw.get('slots')\n    valid = (\n        type(slots) is list and 1 <= len(slots) <= 4\n        and all(type(item) is int and not isinstance(item, bool) and 5 <= item <= 9 for item in slots)\n    )\n    result = {'ok': valid, 'slots': slots if valid else []}"
      }
    }
  ]
}
